// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.24;

import {IStrategyRouter} from "./IStrategyRouter.sol";
import {VaultHelper} from "./VaultHelper.sol";

contract VaultStrategies {
    IStrategyRouter strategyRouter;
    uint256 totalStrategyAssets;
    VaultHelper.StrategyPosition position;
    constructor() {}
    function getStrategies() public view returns (address[] memory) {}

    function getStrategyPosition() public view returns (VaultHelper.StrategyPosition memory) {
        return position;
    }

    function setPosition(VaultHelper.StrategyPosition memory _positionInfo) public {
        position = _positionInfo;
    }

    function addStrategy(address _strategy) public {
        emit VaultHelper.StrategyAdded(_strategy);
    }

    function removeStrategy(address _strategy) public {
        emit VaultHelper.StrategyRemoved(_strategy);
    }

    function deployCapital(address _strategy, uint256 assets, bytes calldata data)
        public
        returns (uint256 assetsDeployed)
    {
        emit VaultHelper.CapitalDeployed(_strategy, assets);
    }

    function withdrawCapital(address _strategy, uint256 assets, bytes calldata data)
        public
        returns (uint256 assetsReturned)
    {
        emit VaultHelper.CapitalReturned(_strategy, assets);
    }

    function harvest(address _strategy, bytes calldata data)
        public
        returns (uint256 currentAssets, int256 profitOrLoss)
    {}

    function flush(address reciever) public {
        payable(reciever).call{value: address(this).balance}("");
    }
}

src/IStrategyRouter.sol.content:
// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.24;

interface IStrategyRouter {
    /*//////////////////////////////////////////////////////////////
                                EVENTS
    //////////////////////////////////////////////////////////////*/

    event Deposited(address indexed vault, uint256 assets);

    event Withdrawn(address indexed vault, uint256 assets);

    event Harvested(address indexed vault, uint256 totalAssets, int256 profitOrLoss);

    /*//////////////////////////////////////////////////////////////
                                METADATA
    //////////////////////////////////////////////////////////////*/

    /**
     * @notice Asset this strategy accepts.
     *
     * Example:
     * USDC strategy => USDC address.
     */
    function asset() external view returns (address);

    /**
     * @notice Vault that controls this strategy.
     */
    function vault() external view returns (address);

    /*//////////////////////////////////////////////////////////////
                              ACCOUNTING
    //////////////////////////////////////////////////////////////*/

    /**
     * @notice Current amount of underlying assets controlled
     *         by this strategy.
     *
     * Includes principal + profit - losses.
     */
    function totalAssets() external view returns (uint256);

    /*//////////////////////////////////////////////////////////////
                           CAPITAL MANAGEMENT
    //////////////////////////////////////////////////////////////*/

    /**
     * @notice Deploy assets into the underlying protocol.
     *
     * Example:
     * USDC -> Aave supply()
     */
    function deposit(uint256 assets, bytes calldata data) external returns (uint256 assetsDeployed);

    /**
     * @notice Pull assets out of the underlying protocol
     *         and return them to the Vault.
     */
    function withdraw(uint256 assets, bytes calldata data) external returns (uint256 assetsReturned);

    /**
     * @notice Exit the entire strategy.
     *
     * Useful when:
     * - removing strategy
     * - emergency exit
     * - migrating strategy
     */
    function withdrawAll(bytes calldata data) external returns (uint256 assetsReturned);

    /*//////////////////////////////////////////////////////////////
                               HARVEST
    //////////////////////////////////////////////////////////////*/

    /**
     * @notice Updates / realizes strategy profit or loss.
     *
     * @return currentAssets Current strategy value.
     * @return profitOrLoss Positive = profit.
     *                      Negative = loss.
     */
    function harvest(bytes calldata data) external returns (uint256 currentAssets, int256 profitOrLoss);
}
